package com.worklink.controller;
import com.worklink.dto.project.*;import com.worklink.service.ProjectService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/client/projects") @PreAuthorize("hasRole('CLIENT')") public class ClientProjectController {final ProjectService s;public ClientProjectController(ProjectService x){s=x;}@PostMapping public ResponseEntity<ProjectResponse> create(@Valid @RequestBody ProjectRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping public List<ProjectResponse> all(){return s.mine();}@GetMapping("/active") public List<ProjectResponse> active(){return s.active();}@GetMapping("/{id}") public ProjectResponse one(@PathVariable Long id){return s.mine(id);}@PutMapping("/{id}") public ProjectResponse update(@PathVariable Long id,@Valid @RequestBody ProjectRequest r){return s.update(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@PatchMapping("/{id}/publish") public ProjectResponse publish(@PathVariable Long id){return s.publish(id);}}
